python3 - <<'EOF'
import json, glob
units = {}
weird = []
for path in sorted(glob.glob('data/*.jsonl')):
    with open(path) as f:
        for i, line in enumerate(f, 1):
            rec = json.loads(line)
            if rec.get('kind') != 'span':
                continue
            el = rec.get('body', {}).get('span', {}).get('elapsed')
            if el is None:
                continue
            units[el.get('unit')] = units.get(el.get('unit'), 0) + 1
            if el.get('value') is None:
                weird.append((path, i, el))
print(units)
print('weird:', weird)
EOF
